"""random_score -- the null reference: an independent uniform draw per
candidate; never queries the target or looks at the shadows.  Its ROC is the
diagonal (TPR = FPR)."""
_FILE = "mia-lab/custom_mia_labelonly.py"
OPS = [{"op": "replace", "file": _FILE, "start_line": 11, "end_line": 63, "content": '''import numpy as np
import torch


class LabelOnlyAttack:
    """Null reference: a uniform random membership score."""

    def __init__(self, info, seed=0):
        self.rng = np.random.default_rng(seed)

    def fit(self, shadow, pool):
        return self

    def score(self, target):
        return self.rng.random(target.idx.shape[0])
'''}]
